def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    players_alive = 1 + len(alive)
    total_demand_units = WATER_REQ * players_alive
    slack = supply - total_demand_units

    prev_bids = []
    rich_threat = 0.0
    desperate_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('budget', 0) > budget:
            rich_threat = max(rich_threat, opp.get('budget', 0))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if not alive:
        return float(min(budget, 8.0))

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    pressure = 0
    if supply <= 16:
        pressure += 3
    elif supply <= 18:
        pressure += 2
    elif supply <= 20:
        pressure += 1
    if slack < 0:
        pressure += 2
    elif slack == 0:
        pressure += 1
    if highest_prev >= 120:
        pressure += 2
    elif highest_prev >= 80:
        pressure += 1
    if desperate_count >= 2:
        pressure += 1

    if urgency == 0 and pressure <= 1 and supply >= 22:
        bid = 1.0
    elif urgency == 0 and pressure <= 2:
        bid = 8.0 + max(0.0, avg_prev * 0.12)
    elif urgency <= 2 and pressure <= 2:
        bid = max(18.0, min(32.0, avg_prev * 0.45 + 6.0))
    elif urgency <= 3 and pressure <= 4:
        bid = max(32.0, min(58.0, highest_prev * 0.55 + 6.0))
    else:
        bid = max(55.0, min(95.0, highest_prev * 0.72 + 8.0))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 82.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 58.0)

    if supply >= 24 and urgency == 0:
        bid = min(bid, 6.0)
    elif supply >= 22 and urgency <= 1:
        bid = min(bid, 14.0)

    if rich_threat > budget * 1.8 and urgency == 0:
        bid = min(bid, 20.0)

    max_safe = budget
    if day <= 3 and hp > 4:
        max_safe = min(max_safe, budget * 0.28 + 6.0)
    elif day <= 6 and hp > 3:
        max_safe = min(max_safe, budget * 0.4 + 8.0)

    bid = min(bid, max_safe)
    if bid < 0:
        bid = 0.0
    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    total_agents_needing_water = num_alive_opponents + 1
    available_water_slots = int(current_supply // WATER_REQ)

    bid_amount = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3:
                if available_water_slots >= total_agents_needing_water:
                    bid_amount = DAILY_SALARY * 0.35
                else:
                    bid_amount = max(DAILY_SALARY * 0.7, highest_prev_bid + 2)
            else:
                bid_amount = max(DAILY_SALARY * 0.95, highest_prev_bid + 5)
        else:
            bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
            if my_hp > 5 and available_water_slots >= total_agents_needing_water + 1:
                bid_amount = min(bid_amount, DAILY_SALARY * 0.4)
    else:
        if my_hp <= 2:
            bid_amount = DAILY_SALARY * 0.9
        elif my_hp <= 4:
            bid_amount = DAILY_SALARY * 0.7
        else:
            bid_amount = DAILY_SALARY * 0.55

    if my_hp <= 1:
        bid_amount = DAILY_SALARY * 0.99

    if available_water_slots < total_agents_needing_water:
        if my_hp <= 3:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.9)
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.75)

    if current_day >= EPISODE_DAYS - 2:
        if my_hp <= 5:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.9)
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.6)

    return min(my_budget, max(0.0, bid_amount))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 40.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 5:
        bid = avg_opp_bid * 1.1
    elif supply < 18:
        bid = avg_opp_bid * 1.05
    else:
        bid = avg_opp_bid * 0.8

    return float(min(my_status['budget'], max(20.0, bid)))
